using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class Inventory{
 static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 public static object Read(){if(EditorApplication.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit scene required");string orig=SceneManager.GetActiveScene().path;var rows=new System.Collections.Generic.List<object>();try{foreach(string f in new[]{"B5","B4","B3"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+f+"_Stealth.unity");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();rows.Add(new{floor=f,objects=all.Select(t=>new{path=P(t),position=new[]{t.position.x,t.position.y,t.position.z},local=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},components=t.GetComponents<Component>().Where(c=>c).Select(c=>c.GetType().Name).ToArray(),children=t.childCount,active=t.gameObject.activeSelf}).ToArray()});}}finally{EditorSceneManager.OpenScene(orig);}string path=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B345_WideInterior/inventory.json"));File.WriteAllText(path,JsonConvert.SerializeObject(rows,Formatting.Indented));return new{path};}
}
